export interface BacklogItem extends RefinedStory {
  id: number;
  order: number;
}

export interface Backlog {
  projectName: string;
  items: BacklogItem[];
}

// -- Import Models --
export interface ExtractedBacklogItems {
  epicSuggestion: string;
  featureSuggestion: string;
  refinedStories: RefinedStory[];
}

