  async validateUserStoryBasic(story: string): Promise<ValidationResult> {
    const systemInstruction = `
      Você é um coach Ágil e Gerente de Produto experiente. Sua tarefa é analisar uma história de usuário com base nos princípios INVEST e fornecer feedback estruturado em formato JSON.
      INVEST significa:
      - Independente: A história deve ser autocontida.
