    sessionId = session.data.id;
    // Simula inatividade
    await new Promise(resolve => setTimeout(resolve, 65 * 1000)); // 1 minuto e 5 segundos
    await api.post('/funnel/jobs/runRescue'); // Executa o job de resgate

    const updatedSession = await api.get(`/funnel/session/${sessionId}`);
    expect(updatedSession.data.stage).toBe('Em Atendimento'); // Volta para atendimento após envio
    expect(updatedSession.data.rescueAttempts).toBe(1);
    // Verifica se a mensagem foi enviada (mock do serviço de mensagens)
    expect(mockMessageService.send).toHaveBeenCalledWith(expect.objectContaining({ message: 'Resgate 1' }));
  });

  it('Deve enviar a segunda mensagem de resgate se o paciente continuar inativo', async () => {
    // Simula inatividade novamente
    await new Promise(resolve => setTimeout(resolve, 65 * 1000));
    await api.post('/funnel/jobs/runRescue');

    const updatedSession = await api.get(`/funnel/session/${sessionId}`);
    expect(updatedSession.data.stage).toBe('Em Atendimento');
    expect(updatedSession.data.rescueAttempts).toBe(2);
    expect(mockMessageService.send).toHaveBeenCalledWith(expect.objectContaining({ message: 'Resgate 2' }));
  });

  it('Deve retomar o fluxo normal se o paciente responder', async () => {
    await api.post(`/funnel/session/${sessionId}/interact`, { type: 'received', content: 'Sim, quero continuar!' });
    const updatedSession = await api.get(`/funnel/session/${sessionId}`);
    expect(updatedSession.data.stage).toBe('Em Atendimento'); // Permanece em atendimento
    // Não deve haver mais tentativas de resgate para esta sessão até nova inatividade
  });
});
