describe('RescueJobService', () => {
  let mockSessionRepository;
  let mockSettingsRepository;
  let mockMessageService;

  beforeEach(() => {
    mockSessionRepository = { findInactive: jest.fn(), update: jest.fn() };
    mockSettingsRepository = { getRescueSettings: jest.fn() };
    mockMessageService = { send: jest.fn() };
  });

  it('should move inactive sessions to rescue stage', async () => {
    const inactiveSession = { id: 's1', stage: 'Em Atendimento', lastInteraction: new Date(Date.now() - 72 * 60 * 60 * 1000), rescueAttempts: 0 };
    mockSessionRepository.findInactive.mockResolvedValue([inactiveSession]);
    mockSettingsRepository.getRescueSettings.mockResolvedValue({ inactivityTime: 24, inactivityTimeUnit: 'horas', maxRescueCycles: 1, rescueMessages: ['Msg1'] });

    await RescueJobService.run(mockSessionRepository, mockSettingsRepository, mockMessageService);

    expect(mockSessionRepository.update).toHaveBeenCalledWith('s1', expect.objectContaining({ stage: 'Em Atendimento', rescueAttempts: 1 }));
    expect(mockMessageService.send).toHaveBeenCalled();
  });

  it('should not send rescue message if max cycles reached', async () => {
    const inactiveSession = { id: 's2', stage: 'Em Atendimento', lastInteraction: new Date(Date.now() - 72 * 60 * 60 * 1000), rescueAttempts: 1 };
    mockSessionRepository.findInactive.mockResolvedValue([inactiveSession]);
    mockSettingsRepository.getRescueSettings.mockResolvedValue({ inactivityTime: 24, inactivityTimeUnit: 'horas', maxRescueCycles: 1, rescueMessages: ['Msg1'] });

    await RescueJobService.run(mockSessionRepository, mockSettingsRepository, mockMessageService);

    expect(mockMessageService.send).not.toHaveBeenCalled();
    expect(mockSessionRepository.update).toHaveBeenCalledWith('s2', expect.objectContaining({ stage: 'Desqualificado' })); // Or Histórico
  });

  it('should not process active sessions', async () => {
    mockSessionRepository.findInactive.mockResolvedValue([]);
    await RescueJobService.run(mockSessionRepository, mockSettingsRepository, mockMessageService);
    expect(mockMessageService.send).not.toHaveBeenCalled();
  });
});
