    mockSessionRepository.findInactive.mockResolvedValue([newContactSession]);
    mockSettingsRepository.getPostRescueDestination.mockResolvedValue({ newContact: 'Desqualificado', existingPatient: 'Histórico' });

    await RescueJobService.run(mockSessionRepository, mockSettingsRepository, mockMessageService);

    expect(mockSessionRepository.update).toHaveBeenCalledWith('s1', expect.objectContaining({ stage: 'Desqualificados' }));
  });

  it('should move existing patient session to "Histórico" if configured', async () => {
    const existingPatientSession = { id: 's2', stage: 'Em Atendimento', lastInteraction: new Date(Date.now() - 2 * 60 * 60 * 1000), rescueAttempts: 1, patientId: 'p1' };
    mockSessionRepository.findInactive.mockResolvedValue([existingPatientSession]);
    mockSettingsRepository.getPostRescueDestination.mockResolvedValue({ newContact: 'Desqualificado', existingPatient: 'Histórico' });

    await RescueJobService.run(mockSessionRepository, mockSettingsRepository, mockMessageService);

    expect(mockSessionRepository.update).toHaveBeenCalledWith('s2', expect.objectContaining({ stage: 'Histórico' }));
  });
});
