describe('API de Geração de Gatilhos de Ações Programadas', () => {
  let patientId1, patientId2;
  let procedureId1, procedureId2;

  beforeAll(async () => {
    // Setup de dados
    const p1 = await api.post('/patients', { name: 'Patient One', phone: '+5511111111111', birthDate: '1990-01-01' });
    patientId1 = p1.data.id;
    const p2 = await api.post('/patients', { name: 'Patient Two', phone: '+5511222222222', birthDate: '1990-05-15' });
    patientId2 = p2.data.id;

    const proc1 = await api.post('/clinic/procedures', { name: 'Proc A', returnCadence: 3, returnCadenceUnit: 'meses', programmedActionActive: true, programmedActionMessage: 'Msg A {nome_paciente}' });
    procedureId1 = proc1.data.id;
    const proc2 = await api.post('/clinic/procedures', { name: 'Proc B', returnCadence: 6, returnCadenceUnit: 'meses', programmedActionActive: false, programmedActionMessage: 'Msg B {nome_paciente}' });
    procedureId2 = proc2.data.id;

    await api.post(`/patients/${patientId1}/history/procedures`, { procedureId: procedureId1, date: '2023-11-12' });
    await api.put('/funnel/settings/programmedActions', { birthdayMessageActive: true, birthdayMessage: 'Happy Bday {nome_paciente}' });
  });

  it('Deve gerar gatilho para retorno de procedimento', async () => {
    // Simula data atual para acionar gatilho (ex: 3 meses - 7 dias antes de 12/02/2024)
    mockDate('2024-02-05T10:00:00Z');
    await api.post('/funnel/jobs/runProgrammedActions');
    const queue = await api.get('/messageQueue');
    expect(queue.data).toEqual(expect.arrayContaining([
      expect.objectContaining({ message: 'Msg A Patient One' })
    ]));
  });

  it('Deve gerar gatilho para mensagem de aniversário', async () => {
    mockDate('1990-05-15T10:00:00Z'); // Simula dia do aniversário
    await api.post('/funnel/jobs/runProgrammedActions');
    const queue = await api.get('/messageQueue');
    expect(queue.data).toEqual(expect.arrayContaining([
      expect.objectContaining({ message: 'Happy Bday Patient Two' })
    ]));
  });

  it('Não deve gerar gatilho para ação desativada', async () => {
    mockDate('2024-05-01T10:00:00Z');
    await api.post('/funnel/jobs/runProgrammedActions');
    const queue = await api.get('/messageQueue');
    expect(queue.data).not.toEqual(expect.arrayContaining([
      expect.objectContaining({ message: expect.stringContaining('Msg B') })
    ]));
  });
});
