          "unit": "```javascript
describe('ProgrammedActionsJobService', () => {
  let mockPatientRepository;
  let mockProcedureRepository;
  let mockSettingsRepository;
  let mockMessageQueueService;

  beforeEach(() => {
    mockPatientRepository = { findAll: jest.fn() };
    mockProcedureRepository = { findById: jest.fn() };
    mockSettingsRepository = { getProgrammedActionSettings: jest.fn() };
    mockMessageQueueService = { addMessage: jest.fn() };
  });

  it('should generate return trigger for eligible patient', async () => {
    const patient = { id: 'p1', name: 'Ana', phone: '123', birthDate: '1990-01-01', procedureHistory: [{ procedureId: 'proc1', date: '2023-01-01' }] };
    const procedure = { id: 'proc1', name: 'Limpeza', returnCadence: 3, returnCadenceUnit: 'meses', programmedActionActive: true, programmedActionMessage: 'Hello {nome_paciente}' };
    mockPatientRepository.findAll.mockResolvedValue([patient]);
    mockProcedureRepository.findById.mockResolvedValue(procedure);
    mockSettingsRepository.getProgrammedActionSettings.mockResolvedValue({ birthdayMessageActive: false });

    jest.spyOn(Date, 'now').mockReturnValue(new Date('2023-04-01T10:00:00Z').getTime()); // 3 months after

    await ProgrammedActionsJobService.run(mockPatientRepository, mockProcedureRepository, mockSettingsRepository, mockMessageQueueService);

    expect(mockMessageQueueService.addMessage).toHaveBeenCalledWith(expect.objectContaining({ message: 'Hello Ana' }));
  });

  it('should generate birthday trigger for eligible patient', async () => {
    const patient = { id: 'p2', name: 'Carlos', phone: '456', birthDate: '1990-05-15', procedureHistory: [] };
    mockPatientRepository.findAll.mockResolvedValue([patient]);
    mockSettingsRepository.getProgrammedActionSettings.mockResolvedValue({ birthdayMessageActive: true, birthdayMessage: 'Happy Bday {nome_paciente}' });

    jest.spyOn(Date, 'now').mockReturnValue(new Date('2023-05-15T10:00:00Z').getTime()); // On birthday

    await ProgrammedActionsJobService.run(mockPatientRepository, mockProcedureRepository, mockSettingsRepository, mockMessageQueueService);

    expect(mockMessageQueueService.addMessage).toHaveBeenCalledWith(expect.objectContaining({ message: 'Happy Bday Carlos' }));
  });

  it('should not generate trigger for inactive action', async () => {
    const patient = { id: 'p3', name: 'Beatriz', phone: '789', procedureHistory: [{ procedureId: 'proc2', date: '2023-01-01' }] };
    const procedure = { id: 'proc2', name: 'Exame', returnCadence: 6, returnCadenceUnit: 'meses', programmedActionActive: false, programmedActionMessage: 'Lembrete' };
    mockPatientRepository.findAll.mockResolvedValue([patient]);
    mockProcedureRepository.findById.mockResolvedValue(procedure);
    mockSettingsRepository.getProgrammedActionSettings.mockResolvedValue({ birthdayMessageActive: false });

    jest.spyOn(Date, 'now').mockReturnValue(new Date('2023-07-01T10:00:00Z').getTime());

    await ProgrammedActionsJobService.run(mockPatientRepository, mockProcedureRepository, mockSettingsRepository, mockMessageQueueService);

    expect(mockMessageQueueService.addMessage).not.toHaveBeenCalled();
  });
});
