describe('PatientService', () => {
  let mockPatientRepository;
  let mockFunnelSessionRepository;

  beforeEach(() => {
    mockPatientRepository = { create: jest.fn(), findByCpfOrPhone: jest.fn(), findById: jest.fn() };
    mockFunnelSessionRepository = { update: jest.fn() };
  });

  it('should create a patient and validate uniqueness', async () => {
    mockPatientRepository.findByCpfOrPhone.mockResolvedValue(null);
    mockPatientRepository.create.mockResolvedValue({ id: 'p1', name: 'Test' });
    const patient = await PatientService.create(mockPatientRepository, { name: 'Test', cpf: '123', phone: '456' });
    expect(patient.name).toBe('Test');
    expect(mockPatientRepository.create).toHaveBeenCalled();
  });

  it('should throw error if CPF or phone already exists', async () => {
    mockPatientRepository.findByCpfOrPhone.mockResolvedValue({ id: 'p1' });
    await expect(PatientService.create(mockPatientRepository, { name: 'Test', cpf: '123', phone: '456' })).rejects.toThrow('CPF ou Telefone já cadastrado');
  });

  it('should link funnel session to existing patient', async () => {
    const existingPatient = { id: 'p1', phone: '+5511999999999' };
    mockPatientRepository.findByCpfOrPhone.mockResolvedValue(existingPatient);
    const session = { id: 's1', from: '+5511999999999' };
    const linkedSession = await FunnelSessionService.linkToPatient(mockFunnelSessionRepository, mockPatientRepository, session);
    expect(linkedSession.patientId).toBe('p1');
    expect(mockFunnelSessionRepository.update).toHaveBeenCalledWith('s1', { patientId: 'p1' });
  });

  it('should create pre-patient on stage transition', async () => {
    const session = { id: 's2', status: 'Pré-Paciente', from: '+5511911111111', collectedData: { name: 'New Patient' } };
    mockPatientRepository.findByCpfOrPhone.mockResolvedValue(null);
    mockPatientRepository.create.mockResolvedValue({ id: 'p2', name: 'New Patient', status: 'Pré-cadastro' });
    const updatedSession = await FunnelSessionService.createPrePatientOnTransition(mockFunnelSessionRepository, mockPatientRepository, session, 'Confirmação de Agendamento');
    expect(updatedSession.patientId).toBe('p2');
    expect(mockPatientRepository.create).toHaveBeenCalledWith(expect.objectContaining({ status: 'Pré-cadastro' }));
  });
});
