          "integration": "```javascript
describe('API de Histórico do Paciente', () => {
  let patientId, professionalId, procedureId;

  beforeAll(async () => {
    const patient = await api.post('/patients', { name: 'Histórico Teste', phone: '+5511911111111' });
    patientId = patient.data.id;
    const professional = await api.post('/clinic/professionals', { name: 'Dr. Teste' });
    professionalId = professional.data.id;
    const procedure = await api.post('/clinic/procedures', { name: 'Limpeza' });
    procedureId = procedure.data.id;
  });

  it('Deve registrar um agendamento manualmente', async () => {
    const appointmentData = { date: '2024-04-01', time: '09:00', professionalId, status: 'Confirmado' };
    const response = await api.post(`/patients/${patientId}/history/appointments`, appointmentData);
    expect(response.status).toBe(201);
    const history = await api.get(`/patients/${patientId}/history`);
    expect(history.data.appointments).toHaveLength(1);
    expect(history.data.appointments[0].date).toBe('2024-04-01');
  });

  it('Deve registrar um procedimento manualmente', async () => {
    const procedureHistoryData = { date: '2024-03-20', procedureId, professionalId };
    const response = await api.post(`/patients/${patientId}/history/procedures`, procedureHistoryData);
    expect(response.status).toBe(201);
    const history = await api.get(`/patients/${patientId}/history`);
    expect(history.data.procedures).toHaveLength(1);
    expect(history.data.procedures[0].date).toBe('2024-03-20');
  });

  it('Deve registrar automaticamente agendamento confirmado pela IA', async () => {
    const iaAppointment = { patientId, date: '2024-04-10', time: '11:00', professionalId, status: 'Confirmado' };
    await api.post('/ia/confirmAppointment', iaAppointment); // Simula IA confirmando
    const history = await api.get(`/patients/${patientId}/history`);
    expect(history.data.appointments).toEqual(expect.arrayContaining([
      expect.objectContaining({ date: '2024-04-10', status: 'Confirmado' })
    ]));
  });
});
