    const appointment = { date: '2024-01-01', time: '10:00', professionalId: 'prof1', status: 'Confirmado' };
    await PatientHistoryService.addAppointment(mockPatientRepository, mockAppointmentHistoryRepository, 'p1', appointment);
    expect(mockAppointmentHistoryRepository.create).toHaveBeenCalledWith(expect.objectContaining({ patientId: 'p1', ...appointment }));
  });

  it('should add procedure to history', async () => {
    mockPatientRepository.findById.mockResolvedValue({ id: 'p1' });
    const procedure = { date: '2024-01-05', procedureId: 'proc1', professionalId: 'prof1' };
    await PatientHistoryService.addProcedure(mockPatientRepository, mockProcedureHistoryRepository, 'p1', procedure);
    expect(mockProcedureHistoryRepository.create).toHaveBeenCalledWith(expect.objectContaining({ patientId: 'p1', ...procedure }));
  });

  it('should automatically add IA confirmed appointment', async () => {
    mockPatientRepository.findById.mockResolvedValue({ id: 'p1' });
    const iaAppointment = { patientId: 'p1', date: '2024-01-10', time: '11:00', professionalId: 'prof1', status: 'Confirmado' };
    await PatientHistoryService.addIAConfirmedAppointment(mockAppointmentHistoryRepository, iaAppointment);
    expect(mockAppointmentHistoryRepository.create).toHaveBeenCalledWith(iaAppointment);
  });
});
