    mockPatientRepository = { findById: jest.fn() };
    mockPaymentHistoryRepository = { create: jest.fn(), findByPatientId: jest.fn() };
  });

  it('should add payment to history', async () => {
    mockPatientRepository.findById.mockResolvedValue({ id: 'p1' });
    const payment = { date: '2024-01-01', value: 100.00, procedureServiceId: 'proc1', observations: 'Cash' };
    await PatientPaymentService.addPayment(mockPatientRepository, mockPaymentHistoryRepository, 'p1', payment);
    expect(mockPaymentHistoryRepository.create).toHaveBeenCalledWith(expect.objectContaining({ patientId: 'p1', ...payment }));
  });

  it('should retrieve payments for a patient', async () => {
    mockPaymentHistoryRepository.findByPatientId.mockResolvedValue([{ value: 50 }]);
    const payments = await PatientPaymentService.getPaymentsByPatientId(mockPaymentHistoryRepository, 'p1');
    expect(payments).toHaveLength(1);
    expect(payments[0].value).toBe(50);
  });

  it('should validate payment value', () => {
    expect(() => PatientPaymentService.validatePayment({ value: -10 })).toThrow('Valor do pagamento deve ser positivo.');
  });
});
