  async generateTechnicalArtifact(technicalConsiderations: string[], identifiedDependencies: string[], type: 'doc' | 'c4-diagram'): Promise<string> {
    const considerationsText = technicalConsiderations.length > 0 ? `### Considerações Técnicas\n${technicalConsiderations.map(c => `- ${c}`).join('\n')}` : '';
    const dependenciesText = identifiedDependencies.length > 0 ? `### Dependências Identificadas\n${identifiedDependencies.map(d => `- ${d}`).join('\n')}` : '';

    const context = `Com base nas seguintes informações de uma história de usuário:\n\n${considerationsText}\n${dependenciesText}`;

    const instructionDoc = `
        Você é um Arquiteto de Software e Redator Técnico Sênior. Sua tarefa é criar um rascunho de documentação técnica em markdown.
        O documento deve ser bem estruturado, usando cabeçalhos, listas e blocos de código, se apropriado.
        O objetivo é fornecer um ponto de partida claro para a equipe de desenvolvimento.
        A saída deve ser APENAS o conteúdo markdown.
    `;

    const instructionDiagram = `
        Você é um Arquiteto de Software Sênior especialista em visualização de sistemas e no modelo C4 para arquitetura de software.
        Sua tarefa é criar um diagrama de arquitetura, preferencialmente um Diagrama de Contêineres (nível 2 do C4), usando a sintaxe C4Context do Mermaid.js.
        O diagrama deve representar o sistema em questão, seus principais contêineres (aplicações, bancos de dados, etc.), e como eles interagem com base nas considerações e dependências da história de usuário.
        Se as informações forem muito genéricas para um diagrama de contêineres, crie um Diagrama de Contexto (nível 1 do C4).
        A saída deve ser APENAS o código Mermaid, sem o bloco de markdown \`\`\`mermaid.
    `;

    const systemInstruction = type === 'doc' ? instructionDoc : instructionDiagram;

    const prompt = `${context}\n\nGere o artefato solicitado.`;

    try {
      const response = await this.ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: {
          systemInstruction,
          temperature: 0.3
        },
      });

      return response.text.trim();
    } catch (error) {
      console.error(`Error calling Gemini API for technical artifact generation:`, error);
      throw new Error(`Falha ao gerar o artefato técnico.`);
    }
  }

  private async generateValidation<T>(story: string, systemInstruction: string, responseSchema: any): Promise<T> {
    let jsonText = '';
    let correctionResponseText = '';
    try {
      // First attempt
      const response = await this.ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: `Com base nas suas instruções, analise e processe a seguinte funcionalidade/descrição: "${story}"`,
        config: {
          systemInstruction,
          responseMimeType: 'application/json',
          responseSchema: responseSchema,
          temperature: 0.4
        },
      });

      jsonText = response.text.trim();
      const parsedResult: T = JSON.parse(jsonText);
      return parsedResult;
    } catch (error) {
      console.error('Initial JSON parse failed. Attempting self-correction.', error);
      console.error('Faulty JSON string:', jsonText);

      if (!jsonText) {
          console.error('Error calling Gemini API or empty response:', error);
          throw new Error('Falha ao receber uma resposta da IA.');
      }

      // Second attempt: Ask the model to fix its own mistake
      try {
        const correctionSystemInstruction = `You are an automated JSON repair tool. You will be given a string that is supposed to be a valid JSON object but contains syntax errors, most likely unescaped double quotes. Your ONLY job is to fix the syntax and return the corrected JSON.

**CRITICAL RULES:**
1. Your entire output MUST be ONLY the raw, valid JSON string.
2. DO NOT wrap the JSON in markdown code blocks (like \`\`\`json ... \`\`\`).
3. DO NOT add any introductory text, explanations, or apologies.
4. The output must start with '{' or '[' and end with '}' or ']'.`;
        const correctionPrompt = `The following string is invalid JSON. Please fix it and return only the valid JSON text.\n\nInvalid JSON:\n${jsonText}`;

        const correctionResponse = await this.ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: correctionPrompt,
            config: {
                systemInstruction: correctionSystemInstruction,
                temperature: 0.0, // Be very deterministic
            }
        });

        correctionResponseText = correctionResponse.text.trim();

        // More robustly find and extract the content of a JSON markdown block
        const markdownRegex = /```(?:json)?\s*([\s\S]*?)\s*```/;
        const match = correctionResponseText.match(markdownRegex);

        if (match && match[1]) {
            // If we found a markdown block, we assume its content is the JSON we want.
            console.log('Stripping markdown fences from corrected JSON.');
            correctionResponseText = match[1].trim();
        }

        const parsedResult: T = JSON.parse(correctionResponseText);
        console.log('Successfully corrected and parsed JSON.');
        return parsedResult;

      } catch (correctionError) {
        console.error('Self-correction attempt failed.', correctionError);
        console.error('Corrected JSON text that failed to parse:', correctionResponseText);
        throw new Error('Falha ao analisar ou receber uma resposta válida do modelo de IA, mesmo após a tentativa de correção.');
      }
    }
  }
}

import { ChangeDetectionStrategy, Component, signal, inject, computed } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { GeminiService } from './services/gemini.service';
import { AnyValidationResult, HistoryItem, RefinedStory, DevelopmentTask, ValidationResult, AdvancedValidationResult, Backlog, BacklogItem, ExtractedBacklogItems, StrategicRefinementResult } from './models/validation.model';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';

declare var marked: any; // Allow TypeScript to recognize the 'marked' library from the CDN

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [CommonModule, FormsModule]
})
export class AppComponent {
  private geminiService = inject(GeminiService);
  private sanitizer = inject(DomSanitizer);

  // View State
  currentView = signal<'welcome' | 'analyzer'>('welcome');

  userStory = signal<string>('Como um novo usuário, eu quero poder me registrar em uma conta usando meu e-mail e senha, para que eu possa acessar os recursos da plataforma.');
  validationResult = signal<AnyValidationResult | null>(null);
  isLoading = signal<boolean>(false);
  activeValidation = signal<'basic' | 'advanced' | 'strategic' | null>(null);
  error = signal<string | null>(null);

  // History State
  history = signal<HistoryItem[]>([]);

  // UI State
  copiedStoryIndex = signal<number | null>(null);
  activeTabs = signal<Record<number, 'bdd' | 'cypress' | 'edge' | 'docs'>>({});
  storyAddedToBacklog = signal<Record<number, boolean>>({});
  activeSideTab = signal<'history' | 'backlog' | 'import'>('history');

  // Alternative formats state
  isGeneratingAltTests = signal<Record<number, boolean>>({});
  alternativeTestResults = signal<Record<number, { format: string; code: string } | null>>({});

  // Technical docs state
  isGeneratingDoc = signal<Record<number, { type: 'doc' | 'c4-diagram' } | null>>({});
  technicalDocumentation = signal<Record<number, { type: 'doc' | 'c4-diagram', content: string } | null>>({});
  isGeneratingDetailedAC = signal<Record<number, boolean>>({});

  // Backlog State
  backlogs = signal<Backlog[]>([]);
  selectedBacklogName = signal<string | null>(null);
  showCreateBacklogInput = signal<boolean>(false);
  newProjectName = signal<string>('');
  editingStory = signal<BacklogItem | null>(null);

  // Import State
  importedFiles = signal<File[]>([]);
  isImporting = signal<boolean>(false);
  importError = signal<string | null>(null);
  importSuccessMessage = signal<string | null>(null);

  activeBacklog = computed(() => {
    const selectedName = this.selectedBacklogName();
    if (!selectedName) return null;
    return this.backlogs().find(b => b.projectName === selectedName) ?? null;
  });

  groupedBacklog = computed(() => {
    const active = this.activeBacklog();
    if (!active || !active.items || active.items.length === 0) {
      return null;
    }

    const grouped = active.items.reduce((acc, item) => {
      const epic = item.epicSuggestion || 'Sem Épico';
      const feature = item.featureSuggestion || 'Sem Feature';

      if (!acc[epic]) {
        acc[epic] = {};
      }
      if (!acc[epic][feature]) {
        acc[epic][feature] = [];
      }
      acc[epic][feature].push(item);
      return acc;
    }, {} as { [epic: string]: { [feature: string]: BacklogItem[] } });

    return grouped;
  });

  objectKeys = Object.keys;

  constructor() {
    this.loadHistoryFromStorage();
    this.loadBacklogsFromStorage();
  }

  // View Management
  showAnalyzer(): void {
    this.currentView.set('analyzer');
    this.activeSideTab.set('history'); // Default to history tab
  }

  showImporter(): void {
    this.currentView.set('analyzer');
    this.activeSideTab.set('import');
  }

  goHome(): void {
      this.currentView.set('welcome');
      // Reset state to provide a fresh start
      this.validationResult.set(null);
      this.error.set(null);
      this.userStory.set('Como um novo usuário, eu quero poder me registrar em uma conta usando meu e-mail e senha, para que eu possa acessar os recursos da plataforma.');
  }

  // History Management
  private loadHistoryFromStorage(): void {
    if (typeof localStorage !== 'undefined') {
      const storedHistory = localStorage.getItem('userStoryHistory');
      if (storedHistory) {
        this.history.set(JSON.parse(storedHistory));
      }
    }
  }

  private addToHistory(userStory: string, result: AnyValidationResult): void {
    const newItem: HistoryItem = {
      id: Date.now(),
      userStory,
      result,
      timestamp: Date.now(),
      model: result.model
    };

    if (result.validationType === 'strategic' && result.refinedStories && result.refinedStories.length > 0) {
        newItem.epicSuggestion = result.refinedStories[0].epicSuggestion;
        newItem.featureSuggestion = result.refinedStories[0].featureSuggestion;

        const totalHours = result.refinedStories.reduce((acc, story) => {
            const hours = parseFloat(story.storyEstimate.replace('h', ''));
            return acc + (isNaN(hours) ? 0 : hours);
        }, 0);
        newItem.storyEstimate = `${totalHours}h`;
    }

    this.history.update(currentHistory => [newItem, ...currentHistory].slice(0, 50)); 
    if (typeof localStorage !== 'undefined') {
      localStorage.setItem('userStoryHistory', JSON.stringify(this.history()));
    }
  }

  loadFromHistory(item: HistoryItem): void {
    this.userStory.set(item.userStory);
    this.validationResult.set(item.result);
    this.error.set(null);
  }

  clearHistory(): void {
    this.history.set([]);
    if (typeof localStorage !== 'undefined') {
      localStorage.removeItem('userStoryHistory');
    }
  }

  // Backlog Management
  private loadBacklogsFromStorage(): void {
    if (typeof localStorage !== 'undefined') {
      const storedBacklogs = localStorage.getItem('userStoryBacklogs');
      if (storedBacklogs) {
        const backlogs: Backlog[] = JSON.parse(storedBacklogs);
        this.backlogs.set(backlogs);
        if (backlogs.length > 0 && !this.selectedBacklogName()) {
          this.selectedBacklogName.set(backlogs[0].projectName);
        }
      }
    }
  }

  private saveBacklogsToStorage(): void {
    if (typeof localStorage !== 'undefined') {
      localStorage.setItem('userStoryBacklogs', JSON.stringify(this.backlogs()));
    }
  }

  createBacklog(): void {
    const name = this.newProjectName().trim();
    if (name && !this.backlogs().some(b => b.projectName === name)) {
      this.backlogs.update(b => [...b, { projectName: name, items: [] }]);
      this.selectedBacklogName.set(name);
      this.saveBacklogsToStorage();
      this.newProjectName.set('');
      this.showCreateBacklogInput.set(false);
    }
  }

  addStoryToBacklog(storyIndex: number): void {
    const active = this.activeBacklog();
    const result = this.validationResult();

    if (!active || !result || result.validationType !== 'strategic') return;
    const story = result.refinedStories[storyIndex];
    if (!story) return;

    const newBacklogItem: BacklogItem = {
      ...story,
      id: Date.now(),
      order: active.items.length
    };

    this.backlogs.update(backlogs => {
      return backlogs.map(b => 
        b.projectName === active.projectName 
          ? { ...b, items: [...b.items, newBacklogItem] }
          : b
      );
    });
    this.saveBacklogsToStorage();
    this.storyAddedToBacklog.update(s => ({ ...s, [storyIndex]: true }));
    setTimeout(() => {
      this.storyAddedToBacklog.update(s => ({ ...s, [storyIndex]: false }));
    }, 2000);
  }

  isStoryInBacklog(storyTitle: string): boolean {
    const active = this.activeBacklog();
    if (!active) return false;
    return active.items.some(item => item.title === storyTitle);
  }

  getStoryIndexInBacklog(storyId: number): number {
    const items = this.activeBacklog()?.items ?? [];
    return items.findIndex(item => item.id === storyId);
  }

  moveStory(storyId: number, direction: 'up' | 'down'): void {
    const active = this.activeBacklog();
    if (!active) return;

    const items = [...active.items];
    const index = items.findIndex(item => item.id === storyId);

    if (index === -1) return;
    if (direction === 'up' && index > 0) {
      [items[index], items[index - 1]] = [items[index - 1], items[index]];
    } else if (direction === 'down' && index < items.length - 1) {
      [items[index], items[index + 1]] = [items[index + 1], items[index]];
    }

    this.backlogs.update(backlogs => 
      backlogs.map(b => b.projectName === active.projectName ? { ...b, items } : b)
    );
    this.saveBacklogsToStorage();
  }

  deleteStory(storyId: number): void {
    const active = this.activeBacklog();
    if (!active || !confirm('Tem certeza que deseja excluir esta história do backlog?')) return;

    this.backlogs.update(backlogs => 
      backlogs.map(b => 
        b.projectName === active.projectName 
        ? { ...b, items: b.items.filter(item => item.id !== storyId) }
        : b
      )
    );
    this.saveBacklogsToStorage();
  }

  startEditing(story: BacklogItem): void {
    this.editingStory.set(JSON.parse(JSON.stringify(story))); // Deep copy to avoid mutating state directly
  }

  saveEditing(): void {
    const editedStory = this.editingStory();
    const active = this.activeBacklog();
    if (!editedStory || !active) return;

    this.backlogs.update(backlogs => 
      backlogs.map(b => 
        b.projectName === active.projectName
        ? { ...b, items: b.items.map(item => item.id === editedStory.id ? editedStory : item) }
        : b
      )
    );
    this.saveBacklogsToStorage();
    this.cancelEditing();
  }

  cancelEditing(): void {
    this.editingStory.set(null);
  }

  viewStoryFromBacklog(story: BacklogItem): void {
    const result: StrategicRefinementResult = {
      validationType: 'strategic',
      model: story.model || 'gemini-2.5-flash',
      divisionAnalysis: `Visualizando a história "${story.title}" a partir do backlog do projeto "${this.selectedBacklogName()}".`,
      refinedStories: [story]
    };

    // Clear previous state and set the new one
    this.validationResult.set(null); // set to null first to ensure change detection triggers for the object
    this.validationResult.set(result);
    this.error.set(null);
    this.isLoading.set(false);
    this.activeValidation.set(null);
    this.storyAddedToBacklog.set({}); // Reset 'added' status
  }

  // UI Actions
  copyToClipboard(story: RefinedStory, index: number): void {
    const textToCopy = this.formatStoryForCopy(story);
    navigator.clipboard.writeText(textToCopy).then(() => {
      this.copiedStoryIndex.set(index);
      setTimeout(() => {
        this.copiedStoryIndex.set(null);
      }, 2000);
    }).catch(err => {
      console.error('Failed to copy text: ', err);
    });
  }

  private formatStoryForCopy(story: RefinedStory): string {
    let content = `
# User Story: ${story.title}
---
**Epic Suggestion:** ${story.epicSuggestion}
**Feature Suggestion:** ${story.featureSuggestion}
---
