            testScenarios: { 
              type: Type.OBJECT, 
              description: 'Objeto contendo cenários de teste E2E, de integração e unitários.',
              properties: {
                  e2e: { type: Type.STRING, description: 'Cenários de teste End-to-End (Cypress) em blocos de código markdown.' },
